/**
 * The failure an interceptor exists to defend against.
 *
 * AUTHORED, not derived — there is no field in any source that states this, and
 * no mechanical way to infer it. The list is deliberately small: it is a filter
 * a human uses to find the entities relevant to a worry ("what stops me merging
 * something unreviewed?"), not a per-entity restatement. Eleven classes over 91
 * entities averages ~8 entities per class; a taxonomy that approached one class
 * per entity would be a renaming, not a filter.
 *
 * An interceptor carries AT LEAST ONE class and may carry several — the same
 * non-exclusivity the computed families have (ontology §4).
 */
export type FailureClass =
  | "unreviewed-merge"
  | "broken-main"
  | "corrupt-record"
  | "secret-exposure"
  | "unfounded-claim"
  | "wrong-workspace"
  | "duplicate-work"
  | "lost-signal"
  | "stale-context"
  | "unrecorded-learning"
  | "blind-enforcement";

export interface FailureClassDefinition {
  /** One sentence: the failure itself. */
  readonly failure: string;
  /** The question a human asks that should surface this class. */
  readonly question: string;
}

