// ---------------------------------------------------------------------------
// Read side — the join that produces a catalog entry (SC3)
// ---------------------------------------------------------------------------

/**
 * The registry metadata a catalog entry needs, passed IN rather than imported
 * so this module stays a dependency-free leaf (`known-guard-names.ts`'s
 * convention). Build it from `GUARD_REGISTRY` at the call site.
 */
export interface RegistryFacts {
  readonly tuningOwnership?: string | undefined;
  readonly hasAttentionCost: boolean;
  readonly hasCanary: boolean;
}

export interface ResolveCatalogInput {
  /** `guardName` -> facts, for names that HAVE a `GuardRegistration`. */
  readonly registryFacts: ReadonlyMap<string, RegistryFacts>;
}

/** The per-registry-field metadata a catalog entry can be missing. */
export type CoverageGap = "tuningOwnership" | "attentionCost" | "canary";

export interface CatalogEntry {
  readonly guardName: string;
  /** Null exactly when `undescribed` is true. */
  readonly description: string | null;
  readonly failureClasses: readonly FailureClass[];
  readonly provenance: readonly string[];
  readonly stratum: Stratum | null;
  readonly subject: "trajectory" | "system";
  readonly filenameNote?: string | undefined;
  readonly note?: string | undefined;
  /**
   * `"implementation"` when `provenance[0]` points at the module implementing
   * the described behavior; `"declaration-only"` when no such module exists and
   * the pointer is a declaration site (see {@link InterceptorDescription}).
   * `"none"` for an undescribed name, which has no provenance at all.
   */
  readonly provenanceStatus: "implementation" | "declaration-only" | "none";
  /**
   * Registry metadata this entity does not have, ALWAYS enumerated rather than
   * defaulted (SC3). For an entity with no `GuardRegistration` at all this is
   * every field, and `registered` is false.
   */
  readonly coverageGaps: readonly CoverageGap[];
  readonly registered: boolean;
  /** True when no authored description exists — the explicit AT2 marker. */
  readonly undescribed: boolean;
}

const ALL_GAPS: readonly CoverageGap[] = ["tuningOwnership", "attentionCost", "canary"];

/**
 * Resolve one `guardName` into a catalog entry.
 *
 * NEVER returns undefined. An unknown name yields `undescribed: true` with a
 * null description and every coverage gap enumerated, so a name that appears in
 * the fire log and nowhere else is rendered as a gap rather than dropped.
 */
export function resolveCatalogEntry(guardName: string, input: ResolveCatalogInput): CatalogEntry {
  const described = INTERCEPTOR_DESCRIPTIONS.get(guardName);
  const facts = input.registryFacts.get(guardName);

  const coverageGaps: CoverageGap[] = facts
    ? [
        ...(facts.tuningOwnership ? [] : (["tuningOwnership"] as const)),
        ...(facts.hasAttentionCost ? [] : (["attentionCost"] as const)),
        ...(facts.hasCanary ? [] : (["canary"] as const)),
      ]
    : [...ALL_GAPS];

  return {
    guardName,
    description: described?.description ?? null,
    failureClasses: described?.failureClasses ?? [],
    provenance: described?.provenance ?? [],
    stratum: described?.stratum ?? null,
    subject: described?.subject === "system" ? "system" : "trajectory",
    filenameNote: described?.filenameNote,
    note: described?.note,
    provenanceStatus:
      described === undefined ? "none" : (described.provenanceStatus ?? "implementation"),
    coverageGaps,
    registered: facts !== undefined,
    undescribed: described === undefined,
  };
}

/** Resolve a whole population. Order is preserved; nothing is filtered. */
export function resolveCatalog(
  guardNames: readonly string[],
  input: ResolveCatalogInput
): CatalogEntry[] {
  return guardNames.map((name) => resolveCatalogEntry(name, input));
}

/**
 * Every `<guardName> -> <path>` whose provenance pointer does not resolve (SC4 / AT3).
 *
 * Takes the existence predicate as a PARAMETER rather than calling `existsSync`
 * itself, so the decision is a pure function testable without touching a disk.
 * `scripts/audit-interceptor-descriptions.ts` supplies the real one; the test
 * suite supplies a fake. Empty result means every pointer resolves.
 */
export function findMissingProvenance(exists: (repoRelativePath: string) => boolean): string[] {
  const missing: string[] = [];
  for (const [guardName, desc] of INTERCEPTOR_DESCRIPTIONS) {
    for (const path of desc.provenance) {
      if (!exists(path)) missing.push(`${guardName} -> ${path}`);
    }
  }
  return missing;
}

/**
 * Failure classes in the `FailureClass` union that the ontology page's table
 * does not document (SC2). The page is the taxonomy's single home, so a class
 * present here and absent there is the start of a second vocabulary.
 */
export function findUndocumentedFailureClasses(ontologyPageBody: string): FailureClass[] {
  return (Object.keys(FAILURE_CLASSES) as FailureClass[]).filter(
    (fc) => !ontologyPageBody.includes(`**\`${fc}\`**`)
  );
}

/** Every entity carrying a given failure class — the filter the taxonomy exists for. */
export function interceptorsByFailureClass(failureClass: FailureClass): string[] {
  const names: string[] = [];
  for (const [name, desc] of INTERCEPTOR_DESCRIPTIONS) {
    if (desc.failureClasses.includes(failureClass)) names.push(name);
  }
  return names.sort();
}
